/**
 * BillingActionStore — auto-generated by .tmp_gen_stores.mjs.
 *
 * Thin store wrapping the Action-side Repository singletons for this feature.
 * Every action delegates to `repo.<method>(...)` inside a try/finally that
 * toggles per-method loading/error state. Follows the §5.4 R5.1 double-export
 * pattern so tests can inject a mock repo via `createBillingActionStore(mock)`.
 *
 * When a feature needs custom orchestration (multi-repo transactions,
 * derived state, cache invalidation) — replace this generated file with a
 * hand-written store; the generator will skip files it did not create.
 */

import { defineStore } from 'pinia'
import { reactive } from 'vue'
import type { RedeemRepository } from '@/features/billing/domain/repositories/redeemRepository'
import { redeemRepository as default_redeem_repo } from '@/features/billing/data/repositories/redeemRepositoryImpl'

export function createBillingActionStore(redeemRepo: RedeemRepository = default_redeem_repo) {
  return defineStore('billing/action', () => {
    const loading = reactive<Record<string, boolean>>({ redeem: false })
    const errors = reactive<Record<string, unknown>>({ redeem: null as unknown })

  const redeem: RedeemRepository['redeem'] = ((...args: unknown[]) => {
    loading.redeem = true
    errors.redeem = null
    return Promise.resolve()
      .then(() => (redeemRepo.redeem as (...a: unknown[]) => unknown)(...args))
      .catch((error: unknown) => { errors.redeem = error; throw error })
      .finally(() => { loading.redeem = false })
  }) as RedeemRepository['redeem']

    return { loading, errors, redeem }
  })
}

export const useBillingActionStore = createBillingActionStore()
